  "response": "<solution>\nimport sys\nimport numpy as np\n\ndef main():\n    # Read all input from standard input as strings to safely parse\n    input_data = sys.stdin.read().split()\n    if not input_data:\n        return\n    \n    n = int(input_data[0])\n    if n < 3:\n        print(0)\n        return\n    \n    # Vectorized reading of the sequence S. Skipping the first element 'n'.\n    S = np.array(input_data[1:n+1], dtype=np.int32)\n    M = int(np.max(S))\n    \n    # Initialize the array for FFT\n    f = np.zeros(M + 1, dtype=np.float64)\n    f[S] = 1.0\n    \n    # Determine the optimal FFT size (next power of 2)\n    size = 2 * M + 1\n    fft_size = 1\n    while fft_size < size:\n        fft_size *= 2\n        \n    # Perform FFT, multiply, and Inverse FFT\n    F = np.fft.rfft(f, fft_size)\n    G = F * F\n    g = np.fft.irfft(G, fft_size)\n    \n    # Vectorized calculation of the answer\n    # For each b in S, we want to access index 2 * b in the polynomial g\n    indices = 2 * S\n    \n    # g is a float array, round to nearest integer and cast to int64\n    counts = np.rint(g[indices]).astype(np.int64)\n    \n    # The coefficient at x^{2B} counts ordered pairs (A, C) with A + C = 2B.\n    # The self pair (B, B) is always counted exactly once, so we subtract 1.\n    # We then divide by 2 to account for ordered pairings (A, C) and (C, A).\n    ans = np.sum((counts - 1) // 2)\n    \n    print(ans)\n\nif __name__ == '__main__':\n    main()\n</solution>",
